import * as THREE from 'three';

const canvas=document.querySelector('#world');
const scene=new THREE.Scene(); scene.background=new THREE.Color('#304835'); scene.fog=new THREE.Fog('#304835',20,39);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.8)); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.18;
const camera=new THREE.OrthographicCamera(-10,10,7,-7,.1,100); camera.position.set(13,18,15); camera.lookAt(0,0,0);
scene.add(new THREE.HemisphereLight(0xdce9cb,0x35402c,2.1)); const sun=new THREE.DirectionalLight(0xffe6bb,3); sun.position.set(-7,15,8); sun.castShadow=true; sun.shadow.mapSize.set(2048,2048); sun.shadow.camera.left=-12;sun.shadow.camera.right=12;sun.shadow.camera.top=12;sun.shadow.camera.bottom=-12;scene.add(sun);
const mat=(color,rough=.9)=>new THREE.MeshStandardMaterial({color,roughness:rough});
const mats={grass:['#668449','#718e4f','#5b7945','#7c9255','#647f49'].map(c=>mat(c)),path:mat('#a18a62'),dirt:mat('#867151'),stone:mat('#898778'),water:mat('#477d78'),dark:mat('#26342a'),gold:mat('#e2bd62',.4),wood:mat('#87603a'),leaf:['#426b3e','#527a42','#66874a','#395b39'].map(c=>mat(c))};
const ground=new THREE.Group();scene.add(ground); const tiles=[]; const objects=[]; const sites={};
const SIZE=1.12, HALF=5; const key=(x,z)=>`${x},${z}`; const toWorld=(x,z)=>({x:(x-HALF)*SIZE,z:(z-HALF)*SIZE});
const siteDefs=[
 {id:'castle',name:'Castle Mythvale',type:'castle',x:1,z:7},
 {id:'camp',name:'Bandit Camp',type:'camp',x:8,z:3},
 {id:'mine',name:'Old Gold Mine',type:'mine',x:8,z:7},
 {id:'ruins',name:'Whispering Ruins',type:'ruins',x:4,z:1},
 {id:'grove',name:'Elderwood Grove',type:'grove',x:2,z:0},
 {id:'crystal',name:'Moonstone Shrine',type:'crystal',x:0,z:3},
];
const siteByCoord=new Map(siteDefs.map(s=>[key(s.x,s.z),s]));
function mesh(geo,material,x,y,z,parent=scene){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function box(parent,x,y,z,w,h,d,material){return mesh(new THREE.BoxGeometry(w,h,d),material,x,y,z,parent)}
function cylinder(parent,x,y,z,rt,rb,h,material,n=7){return mesh(new THREE.CylinderGeometry(rt,rb,h,n),material,x,y,z,parent)}
function sphere(parent,x,y,z,r,material,n=7){return mesh(new THREE.IcosahedronGeometry(r,n),material,x,y,z,parent)}
// A broad, walkable world with hand-painted paths and clear landmark silhouettes.
const paths=new Set(); for(let x=1;x<=8;x++)paths.add(key(x,6));for(let z=3;z<=7;z++)paths.add(key(5,z));for(let x=3;x<=5;x++)paths.add(key(x,2));
for(let z=0;z<11;z++)for(let x=0;x<11;x++){
 const p=toWorld(x,z),site=siteByCoord.get(key(x,z)),isPath=paths.has(key(x,z));
 let t=mesh(new THREE.BoxGeometry(SIZE*.98,.13,SIZE*.98),isPath?mats.path:mats.grass[(x*7+z*11+x*z)%mats.grass.length],p.x,-.08,p.z,ground);t.receiveShadow=true;t.userData={gx:x,gz:z,site};tiles.push(t);
 if(!site&&!isPath&&((x*13+z*19)%13===1)){const tuft=mesh(new THREE.ConeGeometry(.08,.2,4),mats.leaf[(x+z)%4],p.x-.2,.09,p.z+.22,ground);tuft.rotation.z=.2;}
}
const worldFloor=mesh(new THREE.BoxGeometry(15,.4,15),mat('#3d5736'),0,-.34,0,ground);worldFloor.receiveShadow=true;
function makeTree(x,z,scale=1){const group=new THREE.Group();scene.add(group);const p=toWorld(x,z);group.position.set(p.x,0,p.z);cylinder(group,0,.4*scale,0,.12*scale,.18*scale,.8*scale,mat('#62452d'),6);for(let i=0;i<3;i++){const c=sphere(group,0,(.72+i*.27)*scale,0,(.47-i*.07)*scale,mats.leaf[(x+z+i)%4],1);c.scale.set(1,1.1,1);}return group;}
[[0,8],[0,9],[3,9],[5,10],[9,9],[10,8],[10,1],[9,0],[7,0],[0,5],[2,4],[10,5],[6,9],[3,4]].forEach(([x,z],i)=>makeTree(x,z,.8+(i%3)*.17));
function makeCastle(site){const p=toWorld(site.x,site.z),g=new THREE.Group();g.position.set(p.x,0,p.z);scene.add(g);const stone=mat('#b9ad8b'),roof=mat('#7d3e35'),flag=mat('#d6b766');
 box(g,0,.48,0,1.4,.95,1.12,stone);box(g,0,.99,0,1.48,.1,1.2,mat('#6a6654'));
 for(const [x,z] of [[-.62,-.48],[.62,-.48],[-.62,.48],[.62,.48]]){cylinder(g,x,.8,z,.21,.23,1.5,stone,8);cylinder(g,x,1.62,z,.25,.04,.48,roof,8);box(g,x,1.98,z,.025,.42,.025,mat('#58372c'));const f=box(g,x+.09,2.02,z,.22,.13,.025,flag);f.rotation.z=-.1;}
 box(g,0,.32,.57,.3,.58,.08,mat('#453d30'));box(g,0,.35,.525,.16,.44,.03,mat('#382f25'));site.mesh=g;site.look='♜';objects.push({object:g,site});
}
function makeCamp(site){const p=toWorld(site.x,site.z),g=new THREE.Group();g.position.set(p.x,0,p.z);scene.add(g);const cloth=mat('#915043'),wood=mat('#614a34');
 for(let i=0;i<3;i++){const x=(i-1)*.48,z=(i%2)*.34-.13;const tent=mesh(new THREE.ConeGeometry(.39,.66,4),cloth,x,.33,z,g);tent.rotation.y=Math.PI/4;box(g,x,.12,z+.08,.28,.05,.08,wood);}
 cylinder(g,0,.13,.62,.22,.25,.22,mat('#383329'),8);const flame=sphere(g,0,.32,.62,.12,mat('#ed994a',.5),1);flame.scale.y=1.7;
 site.mesh=g;site.look='⚑';objects.push({object:g,site});
}
function makeMine(site){const p=toWorld(site.x,site.z),g=new THREE.Group();g.position.set(p.x,0,p.z);scene.add(g);const rock=mat('#75776b'),wood=mat('#65482d');for(let i=0;i<4;i++){const b=sphere(g,Math.cos(i*1.7)*.4,.24,Math.sin(i*1.7)*.34,.4,rock,0);b.scale.y=.7;}box(g,0,.38,0,.66,.72,.08,wood);box(g,0,.08,.04,.76,.1,.16,mat('#362f25'));for(let i=0;i<3;i++)sphere(g,-.24+i*.23,.2,.11,.08,mats.gold,1);site.mesh=g;site.look='✦';objects.push({object:g,site});}
function makeRuins(site){const p=toWorld(site.x,site.z),g=new THREE.Group();g.position.set(p.x,0,p.z);scene.add(g);const stone=mat('#aaa58d');for(const [x,z,h] of [[-.32,-.12,.8],[.31,.04,.59],[-.05,.32,.42]]){box(g,x,h/2,z,.2,h,.22,stone);box(g,x,h,z,.3,.14,.29,mat('#787564'));}const ring=cylinder(g,0,.1,0,.52,.52,.08,mat('#6f6959'),8);ring.rotation.x=Math.PI/2;site.mesh=g;site.look='⌘';objects.push({object:g,site});}
function makeGrove(site){const p=toWorld(site.x,site.z),g=new THREE.Group();g.position.set(p.x,0,p.z);scene.add(g);for(let i=0;i<4;i++){const x=(i%2)*.43-.2,z=Math.floor(i/2)*.38-.2;cylinder(g,x,.37,z,.09,.13,.72,mat('#59452f'),6);sphere(g,x,.85,z,.38,mats.leaf[i],1);}site.mesh=g;site.look='♠';objects.push({object:g,site});}
function makeShrine(site){const p=toWorld(site.x,0); /* replaced below */}
siteDefs.forEach(s=>({castle:makeCastle,camp:makeCamp,mine:makeMine,ruins:makeRuins,grove:makeGrove}[s.type])(s));
// Moonstone shrine: floating crystal in a weathered ring.
{const s=siteDefs.find(s=>s.type==='crystal'),p=toWorld(s.x,s.z),g=new THREE.Group();g.position.set(p.x,0,p.z);scene.add(g);cylinder(g,0,.12,0,.5,.5,.18,mat('#847d68'),8);const c=mesh(new THREE.OctahedronGeometry(.35,0),mat('#8de0d4',.28),0,.72,0,g);c.rotation.z=.12;for(let i=0;i<3;i++)box(g,(i-1)*.26,.24,.05,.12,.38,.12,mat('#a6a18b'));s.mesh=g;s.look='◆';objects.push({object:g,site:s});}
// Little pennant and a low-poly rider, designed to read from the strategy-map camera.
const hero=new THREE.Group();scene.add(hero);const armor=mat('#a8b48e'),cloth=mat('#9a463a'),skin=mat('#d3b68b'),metal=mat('#d4c697',.5),horse=mat('#77553c');
const hbody=sphere(hero,0,.52,0,.37,horse,1);hbody.scale.set(1.25,.78,.76);sphere(hero,0,.66,-.32,.2,horse,1);for(const x of [-.22,.22])for(const z of [-.2,.2])cylinder(hero,x,.27,z,.055,.07,.45,mat('#44382b'),5);
box(hero,0,.99,0,.28,.42,.3,armor);sphere(hero,0,1.34,.02,.17,skin,1);const helm=cylinder(hero,0,1.49,.02,.14,.05,.17,metal,6);helm.rotation.x=Math.PI;box(hero,0,1.57,.02,.02,.12,.02,mat('#d3b35e'));box(hero,.27,1.05,0,.18,.23,.1,cloth);const sword=box(hero,.37,.9,-.08,.055,.52,.055,metal);sword.rotation.z=-.35;
let heroPos={x:2,z:7},moves=5,day=1,gold=650,woodCount=8,crystalCount=3,army=12,selected=true,activeBattle=null,toastTimer;
function placeHero(){const p=toWorld(heroPos.x,heroPos.z);hero.position.set(p.x,.02,p.z);}placeHero();
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let dragging=null,dragMoved=false;
const state={cleared:false,collected:new Set(),built:false,defeated:false};
function syncUI(){document.querySelector('#goldCount').textContent=gold;document.querySelector('#woodCount').textContent=woodCount;document.querySelector('#crystalCount').textContent=crystalCount;document.querySelector('#armyCount').textContent=army;document.querySelector('#movesCount').textContent=moves;document.querySelector('#dayLabel').textContent=`DAY ${day}`;document.querySelector('#questText').textContent=state.cleared?'Claim the crown of Mythvale':'Clear the bandit camp';document.querySelector('#questSub').textContent=state.cleared?'The eastern road is yours. A kingdom awaits.':'The road east is not safe.';}syncUI();
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function resize(){const w=innerWidth,h=innerHeight;renderer.setSize(w,h,false);const aspect=w/h;let viewH=13.8;if(aspect<1)viewH=18;const viewW=viewH*aspect;camera.left=-viewW/2;camera.right=viewW/2;camera.top=viewH/2;camera.bottom=-viewH/2;camera.updateProjectionMatrix();}addEventListener('resize',resize);resize();
let zoom=1;function setZoom(v){zoom=Math.max(.68,Math.min(1.45,v));camera.zoom=zoom;camera.updateProjectionMatrix();}
document.querySelector('#zoomIn').onclick=()=>setZoom(zoom*1.12);document.querySelector('#zoomOut').onclick=()=>setZoom(zoom/1.12);document.querySelector('#homeView').onclick=()=>{camera.position.set(13,18,15);camera.lookAt(0,0,0);setZoom(1);};
function coordFromPointer(e){const r=canvas.getBoundingClientRect();pointer.x=(e.clientX-r.left)/r.width*2-1;pointer.y=-((e.clientY-r.top)/r.height*2-1);raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(tiles,false);return hits.length?hits[0].object.userData:null;}
canvas.addEventListener('pointerdown',e=>{dragging={x:e.clientX,y:e.clientY,cx:camera.position.x,cz:camera.position.z};dragMoved=false;canvas.setPointerCapture(e.pointerId)});
canvas.addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-dragging.x,dy=e.clientY-dragging.y;if(Math.abs(dx)+Math.abs(dy)>7)dragMoved=true;if(dragMoved){const scale=14/(innerHeight*zoom);camera.position.x=dragging.cx-dx*scale*.72;camera.position.z=dragging.cz+dx*scale*.72+dy*scale*1.2;camera.updateProjectionMatrix();}});
canvas.addEventListener('pointerup',e=>{if(!dragging)return;const moved=dragMoved;dragging=null;if(!moved)handleClick(e)});
function siteAt(x,z){return siteByCoord.get(key(x,z));}
function handleClick(e){if(activeBattle)return;const r=canvas.getBoundingClientRect();pointer.x=(e.clientX-r.left)/r.width*2-1;pointer.y=-((e.clientY-r.top)/r.height*2-1);raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects(tiles,false)[0];if(!hit)return;const {gx:x,gz:z,site}=hit.object.userData;if(site){interactSite(site);return}if(x===heroPos.x&&z===heroPos.z){toast('Sir Aldric — ready for your command');return}moveHero(x,z);}
function findPath(sx,sz,tx,tz){const q=[[sx,sz]],prev=new Map([[key(sx,sz),null]]);while(q.length){const [x,z]=q.shift();if(x===tx&&z===tz)break;for(const [nx,nz] of [[x+1,z],[x-1,z],[x,z+1],[x,z-1]]){if(nx<0||nx>10||nz<0||nz>10||siteAt(nx,nz)?.type==='castle'||siteAt(nx,nz)?.type==='camp'||siteAt(nx,nz)?.type==='mine'||siteAt(nx,nz)?.type==='ruins'||siteAt(nx,nz)?.type==='grove'||siteAt(nx,nz)?.type==='crystal')continue;const k=key(nx,nz);if(!prev.has(k)){prev.set(k,key(x,z));q.push([nx,nz]);}}}if(!prev.has(key(tx,tz)))return null;const path=[];let k=key(tx,tz);while(k!==key(sx,sz)){const [x,z]=k.split(',').map(Number);path.unshift({x,z});k=prev.get(k);}return path;}
function moveHero(x,z){const path=findPath(heroPos.x,heroPos.z,x,z);if(!path||!path.length){toast('That way is blocked.');return}if(path.length>moves){toast('Not enough movement points. End your turn to recover.');return}moves-=path.length;heroPos={x,z};placeHero();syncUI();toast(`Sir Aldric moves ${path.length} ${path.length===1?'space':'spaces'}.`);if(siteAt(x,z))interactSite(siteAt(x,z));}
function interactSite(site){if(site.type==='castle'){openTown();return}if(site.type==='camp'){if(state.cleared){openInfo('Bandit Camp','The camp is quiet now. The road is yours.', 'CONTINUE');return}if(!state.defeated){openBattle();return}}
 if(state.collected.has(site.id)){openInfo(site.name,'You have already claimed the treasure here. The wilds hold no more for now.','CONTINUE');return}
 const content={mine:['Old Gold Mine','A forgotten seam of gold still glimmers in the hillside. Your miners gather 300 gold.'],ruins:['Whispering Ruins','Among the fallen stones you discover a sealed reliquary. It holds 150 gold and a moonstone.'],grove:['Elderwood Grove','The grove yields fine timber for your kingdom. You gather 6 wood.'],crystal:['Moonstone Shrine','A shard of pure moonstone hums with old magic. You collect 2 crystals.']};const [title,desc]=content[site.type];openInfo(title,desc,site.type==='mine'?'CLAIM 300 GOLD':'CLAIM TREASURE',()=>{state.collected.add(site.id);if(site.type==='mine')gold+=300;if(site.type==='ruins'){gold+=150;crystalCount+=1}if(site.type==='grove')woodCount+=6;if(site.type==='crystal')crystalCount+=2;syncUI();toast('Treasure added to your stores.');});}
function openInfo(title,text,action='CONTINUE',onAccept=()=>{}){showModal(`<div class="modal-kicker">LANDMARK DISCOVERED</div><h2>${title}</h2><p>${text}</p><div class="modal-actions"><button class="game-btn" id="accept">${action}</button></div>`,()=>{document.querySelector('#accept')?.addEventListener('click',()=>{onAccept();closeModal()})})}
function showModal(html,bind){const root=document.querySelector('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><button class="modal-close" aria-label="Close">×</button>${html}</div></div>`;root.querySelector('.modal-close').onclick=closeModal;root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});bind?.();}
function closeModal(){document.querySelector('#modalRoot').innerHTML=''}
function openTown(){showModal(`<div class="modal-kicker">YOUR SEAT OF POWER · MYTHVALE</div><h2>Castle Mythvale</h2><p>The old keep stands ready to shelter a new army. Recruit troops to strengthen Sir Aldric's forces.</p><div class="town-grid"><div class="recruit-card"><strong>🛡 Swordsmen</strong><small>+5 soldiers · Cost: 250 gold</small><button class="game-btn" id="recruit">RECRUIT</button></div><div class="recruit-card"><strong>🏹 Longbowmen</strong><small>+3 archers · Cost: 200 gold</small><button class="game-btn" id="archers">RECRUIT</button></div></div><div class="modal-actions"><button class="game-btn secondary" id="leave">LEAVE CASTLE</button></div>`,()=>{document.querySelector('#recruit').onclick=()=>recruit(250,5);document.querySelector('#archers').onclick=()=>recruit(200,3);document.querySelector('#leave').onclick=closeModal})}
function recruit(cost,count){if(gold<cost){toast('Not enough gold.');return}gold-=cost;army+=count;syncUI();toast(`${count} troops join your army.`);closeModal();openTown()}

function openBattle(){activeBattle={enemy:8,ally:army,round:0};renderBattle()}
function renderBattle(status='Bandits block the road! Choose your action.'){if(!activeBattle)return;const b=activeBattle;showModal(`<div class="modal-kicker">A HOSTILE ARMY APPROACHES</div><h2>Battle for the East Road</h2><div class="fight-head"><div class="army-panel"><small>YOUR ARMY</small><strong>Sir Aldric</strong><span class="troop">⚔ ${b.ally} soldiers</span></div><div class="vs">VS</div><div class="army-panel"><small>ENEMY FORCES</small><strong>Road bandits</strong><span class="troop">☠ ${b.enemy} raiders</span></div></div><div class="battle-arena"><div class="battle-grid"><div class="battle-unit ally">♞<span>${b.ally} · KNIGHTS</span></div><div class="vs">⚔</div><div class="battle-unit enemy">♟<span>${b.enemy} · BANDITS</span></div></div></div><div class="battle-status" id="battleStatus">${status}</div><div class="modal-actions battle-actions"><button class="game-btn secondary" id="retreat">RETREAT</button><button class="game-btn" id="strike">⚔ &nbsp; STRIKE</button></div>`,()=>{document.querySelector('#strike').onclick=battleStrike;document.querySelector('#retreat').onclick=()=>{activeBattle=null;closeModal();toast('You withdraw to regroup.')}})}
function battleStrike(){if(!activeBattle)return;const b=activeBattle;b.round++;const hit=Math.min(b.enemy,2+Math.floor(Math.random()*3));b.enemy-=hit;if(b.enemy<=0){b.enemy=0;activeBattle=null;state.cleared=true;state.defeated=true;gold+=250;army=Math.max(1,b.ally);syncUI();showModal(`<div class="modal-kicker">VICTORY · EAST ROAD SECURED</div><h2>The Bandits are Broken</h2><p>Sir Aldric's forces scatter the raiders. The road to the east is safe once more. The grateful villagers send 250 gold to your treasury.</p><div class="modal-actions"><button class="game-btn" id="victory">CLAIM YOUR REWARD</button></div>`,()=>document.querySelector('#victory').onclick=()=>{closeModal();toast('Victory! 250 gold added to your treasury.');syncUI()});return}
 const loss=Math.min(b.ally,Math.max(1,Math.floor(Math.random()*3)));b.ally-=loss;army=Math.max(0,b.ally);if(b.ally<=0){activeBattle=null;army=1;syncUI();showModal(`<div class="modal-kicker">DEFEAT · THE HERO LIVES</div><h2>Forced to Retreat</h2><p>Your soldiers are scattered, but Sir Aldric escapes. Return to Castle Mythvale and recruit reinforcements before trying again.</p><div class="modal-actions"><button class="game-btn" id="retreatDone">REGROUP</button></div>`,()=>document.querySelector('#retreatDone').onclick=()=>{closeModal();toast('Return to the castle to rebuild your army.')});return}syncUI();renderBattle(`Your army strikes for ${hit}! The raiders hit back — ${loss} troops lost.`)}
document.querySelector('#endTurn').onclick=()=>{if(activeBattle)return;day++;moves=5;if(state.collected.has('mine'))gold+=100;syncUI();toast(day===2?'A new day dawns. Your hero is rested.':'Turn ended. Movement restored.');};
// Subtle flags and magical glimmers lend motion without distracting from the map.
let t=0;function animate(){requestAnimationFrame(animate);t+=.016;hero.position.y=.02+Math.sin(t*2.2)*.025;hero.rotation.y=Math.sin(t*.7)*.055;for(const s of siteDefs){if(s.type==='crystal'&&s.mesh){s.mesh.children.forEach(c=>{if(c.geometry.type==='OctahedronGeometry'){c.rotation.y+=.012;c.position.y=.72+Math.sin(t*2)*.06}})}}renderer.render(scene,camera)}animate();
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='+'||e.key==='=')setZoom(zoom*1.1);if(e.key==='-')setZoom(zoom/1.1);if(e.key==='Enter')document.querySelector('#endTurn').click()});

