function showModal(html,bind){const root=document.querySelector('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><button class="modal-close" aria-label="Close">×</button>${html}</div></div>`;root.querySelector('.modal-close').onclick=closeModal;root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});bind?.()}function closeModal(){document.querySelector('#modalRoot').innerHTML=''}
function openTown(){showModal(`<div class="modal-kicker">YOUR SEAT OF POWER · MYTHVALE</div><h2>Castle Mythvale</h2><p>The old keep stands ready to shelter a new army. Recruit troops to strengthen Sir Aldric's forces.</p><div class="town-grid"><div class="recruit-card"><strong>🛡 Swordsmen</strong><small>+5 soldiers · Cost: 250 gold</small><button class="game-btn" id="recruit">RECRUIT</button></div><div class="recruit-card"><strong>🏹 Longbowmen</strong><small>+3 archers · Cost: 200 gold</small><button class="game-btn" id="archers">RECRUIT</button></div></div><div class="modal-actions"><button class="game-btn secondary" id="leave">LEAVE CASTLE</button></div>`,()=>{document.querySelector('#recruit').onclick=()=>recruit(250,5);document.querySelector('#archers').onclick=()=>recruit(200,3);document.querySelector('#leave').onclick=closeModal})}function recruit(cost,count){if(gold<cost){toast('Not enough gold.');return}gold-=cost;army+=count;syncUI();toast(`${count} troops join your army.`);closeModal();openTown()}

