function moveHero(x,z){const path=findPath(heroPos.x,heroPos.z,x,z);if(!path||!path.length){toast('That way is blocked.');return}if(path.length>moves){toast('Not enough movement points. End your turn to recover.');return}moves-=path.length;heroPos={x,z};placeHero();syncUI();toast(`Sir Aldric moves ${path.length} ${path.length===1?'space':'spaces'}.`)}
function approachSite(site){const neighbors=[[site.x+1,site.z],[site.x-1,site.z],[site.x,site.z+1],[site.x,site.z-1]].filter(([x,z])=>x>=0&&x<=10&&z>=0&&z<=10&&!siteAt(x,z));const routes=neighbors.map(([x,z])=>findPath(heroPos.x,heroPos.z,x,z)).filter(Boolean).sort((a,b)=>a.length-b.length);const path=routes[0];if(!path){toast('There is no clear path to that landmark.');return}if(path.length===0){interactSite(site);return}if(moves===0){toast('End your turn to restore movement.');return}const steps=Math.min(moves,path.length),dest=path[steps-1];moves-=steps;heroPos={x:dest.x,z:dest.z};placeHero();syncUI();if(steps===path.length){toast(`Sir Aldric reaches ${site.name}.`);interactSite(site)}else toast(`Sir Aldric advances ${steps} spaces toward ${site.name}.`)}
