function recruit(cost,count){if(gold<cost){toast('Not enough gold.');return}gold-=cost;army+=count;syncUI();toast(`${count} troops join your army.`);closeModal();openTown()}
function openBattle(){activeBattle={enemy:11};renderBattle('The bandits block the road. Choose your moment.')}function renderBattle(status){if(!activeBattle)return;const enemy=activeBattle.enemy;showModal(`<div class="modal-kicker">A ROAD ENCOUNTER</div><h2>Bandit Camp</h2><div class="fight-head"><div class="army-panel"><small>MYTHVALE</small><strong>Sir Aldric</strong><span class="troop">⚔ ${army} soldiers</span></div><div class="vs">VS</div><div class="army-panel"><small>HOSTILE</small><strong>Bandits</strong><span class="troop">⚔ ${enemy} raiders</span></div></div><div class="battle-arena"><div class="battle-grid"><div class="battle-unit ally">♞<span>${army} soldiers</span></div><div class="vs">⚔</div><div class="battle-unit enemy">⚑<span>${enemy} raiders</span></div></div></div><div class="battle-status">${status}</div><div class="modal-actions battle-actions"><button class="game-btn secondary" id="retreat">RETREAT</button><button class="game-btn" id="attack">ATTACK</button></div>`,()=>{document.querySelector('#attack').onclick=fightRound;document.querySelector('#retreat').onclick=retreatBattle})}
function fightRound(){if(!activeBattle)return;const damage=Math.max(2,Math.floor((army+3)*.43));activeBattle.enemy=Math.max(0,activeBattle.enemy-damage);if(activeBattle.enemy===0){state.cleared=true;activeBattle=null;syncUI();showModal(`<div class="modal-kicker">VICTORY</div><h2>The Road Is Clear</h2><p>The bandits break and flee into the wilds. Sir Aldric's surviving troops rally beneath the banners of Mythvale.</p><div class="modal-actions"><button class="game-btn" id="continue">CONTINUE</button></div>`,()=>document.querySelector('#continue').onclick=closeModal);return}const losses=Math.min(army,Math.max(1,Math.ceil(activeBattle.enemy*.14)));army-=losses;syncUI();if(army<=0){army=0;syncUI();activeBattle=null;showModal(`<div class="modal-kicker">DEFEAT</div><h2>Your Army Is Routed</h2><p>Sir Aldric retreats to Mythvale. Recruit fresh troops at the castle before challenging the bandits again.</p><div class="modal-actions"><button class="game-btn" id="continue">CONTINUE</button></div>`,()=>document.querySelector('#continue').onclick=closeModal);return}renderBattle(`Your troops deal ${damage} damage. ${losses} soldiers fall in the counterattack.`)}function retreatBattle(){if(!activeBattle)return;activeBattle=null;closeModal();toast('Sir Aldric retreats from the bandit camp.')}
function endTurn(){if(activeBattle)return;day++;moves=5;gold+=50;const seasons=['EARLY SUMMER','HIGH SUMMER','AUTUMN','WINTER'];document.querySelector('#seasonLabel').textContent=seasons[Math.floor((day-1)/7)%seasons.length];syncUI();toast('A new day dawns. +50 gold and movement restored.')}
document.querySelector('#endTurn').addEventListener('click',endTurn);
function goHome(){camera.position.set(13,18,15);camera.lookAt(0,0,0);setZoom(1)}
document.querySelector('#homeView').onclick=goHome;
function onKeyDown(e){if(e.key==='Escape'){if(activeBattle)retreatBattle();else closeModal();return}if(document.querySelector('#modalRoot').innerHTML)return;if(e.key==='Enter'||e.key.toLowerCase()==='e'){endTurn();return}if(e.key==='+'||e.key==='=')setZoom(zoom*1.12);if(e.key==='-')setZoom(zoom/1.12);if(e.key.toLowerCase()==='h')goHome()}addEventListener('keydown',onKeyDown);
const clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);const t=clock.getElapsedTime();hero.position.y=.02+Math.sin(t*2.2)*.025;hero.rotation.y=Math.sin(t*.55)*.04;for(const entry of objects){if(entry.site.type==='camp'&&!state.cleared)entry.object.rotation.y=Math.sin(t*1.5)*.035}renderer.render(scene,camera)}animate();

