import {createRequire} from 'node:module';
const require=createRequire('/home/runner/.local/share/omgithub-playwright/package.json'); const {chromium}=require('playwright');
const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox','--enable-webgl','--enable-unsafe-swiftshader','--use-gl=angle','--use-angle=swiftshader']});
const page=await browser.newPage({viewport:{width:1280,height:800}}); const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});await page.goto('http://127.0.0.1:3002');await page.waitForTimeout(1200);
const points=await page.evaluate(async()=>{const T=await import('/node_modules/three/build/three.module.js');const c=new T.OrthographicCamera(-11.04,11.04,6.9,-6.9,.1,100);c.position.set(13,18,15);c.lookAt(0,0,0);c.updateProjectionMatrix();const coords={castle:[1,7],camp:[8,3],mine:[8,7],ruins:[4,1],grove:[2,0],crystal:[0,3]};return Object.fromEntries(Object.entries(coords).map(([k,[x,z]])=>{const v=new T.Vector3((x-5)*1.12,0,(z-5)*1.12).project(c);return[k,{x:(v.x+1)*640,y:(1-v.y)*400}]}))});
console.log('points',points,'initial',await page.locator('#armyCount').textContent(),'quest',await page.locator('#questText').textContent(),'errors',errors);
async function clickSite(id){const p=points[id];await page.mouse.click(p.x,p.y);await page.waitForTimeout(150);}
await clickSite('castle');console.log('castle modal',await page.locator('.modal h2').textContent()); await page.locator('#archers').click();console.log('recruit',await page.locator('#armyCount').textContent(),await page.locator('#goldCount').textContent());await page.locator('#leave').click();
await clickSite('crystal');console.log('crystal modal',await page.locator('.modal h2').textContent());if(await page.locator('#accept').count())await page.locator('#accept').click();console.log('crystals',await page.locator('#crystalCount').textContent());
for(let i=0;i<5;i++){if(await page.locator('#modalRoot .modal').count())break;await clickSite('camp');if((await page.locator('#modal h2').count())&&await page.locator('.modal h2').textContent()==='Bandit Camp')break;if(i<4)await page.locator('#endTurn').click();}
console.log('camp state',await page.locator('.modal h2').allTextContents(),'moves',await page.locator('#movesCount').textContent(),'day',await page.locator('#dayLabel').textContent(),'errors',errors);
if(await page.locator('#attack').count()){for(let i=0;i<5&&await page.locator('#attack').count();i++){await page.locator('#attack').click();await page.waitForTimeout(80);} console.log('battle outcome',await page.locator('.modal h2').textContent(),'army',await page.locator('#armyCount').textContent());}
console.log('final errors',errors); await browser.close();
